const item = $input.first().json;
const body = item.body || item;

const rawUrl = (body.video_url || body.video_id || '').trim();
const regExp = /^.*(youtu.be\/|v\/|u\/\w\/|embed\/|watch\?v=|\&v=|shorts\/)([^#\&\?]*).*/;
const match = (rawUrl || '').match(regExp);
let videoId = (match && match[2].length === 11) ? match[2] : '';
if (!videoId && rawUrl.length === 11) {
  videoId = rawUrl;
}
if (!videoId) {
  videoId = 'ic4HSdThFc8';
}

const isShort = rawUrl.includes('shorts');
const cleanUrl = isShort ? `https://www.youtube.com/shorts/${videoId}` : `https://www.youtube.com/watch?v=${videoId}`;
const defaultThumb = `https://i.ytimg.com/vi/${videoId}/hqdefault.jpg`;
const customImage = body.image_url || defaultThumb;

return [{
  json: {
    videoId: videoId,
    cleanUrl: cleanUrl,
    platform: isShort ? 'youtube_shorts' : 'youtube',
    imageUrl: customImage,
    scheduledAt: body.scheduled_at || new Date().toISOString(),
    publishNow: !!body.publish_now,
    businessName: body.business_name || '',
    notes: body.notes || ''
  }
}];

const ytResp = $input.first().json;
const prev = $('Extract Video ID & Router').item.json;

const item = (ytResp.items && ytResp.items[0]) ? ytResp.items[0].snippet : {};
const title = item.title || 'Marketing Video';
let description = item.description || '';
if (description.length > 2500) {
  description = description.substring(0, 2500) + '...';
}
const tags = item.tags ? item.tags.slice(0, 6).join(', ') : '';
const thumbs = item.thumbnails || {};
const ytThumb = thumbs.maxres?.url || thumbs.high?.url || thumbs.medium?.url || prev.imageUrl;

return [{
  json: {
    ...prev,
    videoTitle: title,
    videoDescription: description,
    videoTags: tags,
    finalImageUrl: (prev.imageUrl && !prev.imageUrl.includes('hqdefault.jpg')) ? prev.imageUrl : ytThumb
  }
}];

