parameters.jsCode:
const groqResp = $input.first().json;
const ctx = $('Prepare Video Context for AI').item.json;

let hook = '';
let summary = '';
let content = '';
let hashtags = '#Video #Marketing #Insights';
let cta = `Watch the full video on YouTube: ${ctx.cleanUrl}`;

try {
  const choice = groqResp.choices[0].message.content;
  const parsed = JSON.parse(choice);
  hook = parsed.hook || '';
  summary = Array.isArray(parsed.summary) ? parsed.summary.join('\n• ') : (parsed.summary || '');
  content = parsed.generated_content || '';
  hashtags = parsed.hashtags || hashtags;
  cta = parsed.call_to_action || cta;
} catch (e) {
  content = groqResp.choices?.[0]?.message?.content || ctx.videoTitle;
  hook = `🎬 New Video: ${ctx.videoTitle}`;
}

if (cta && !cta.includes(ctx.cleanUrl)) {
  cta += ` 👉 ${ctx.cleanUrl}`;
}

const fullContent = (hook ? `🔥 ${hook}\n\n` : '') + content + (summary ? `\n\n📌 Key Highlights:\n${summary}` : '');

const metaObj = {
  video_url: ctx.cleanUrl,
  image_url: ctx.finalImageUrl,
  scheduled_at: ctx.scheduledAt,
  hook: hook,
  summary: summary
};

const record = {
  topic: ctx.videoTitle,
  business_name: ctx.businessName,
  audience: 'Creators & Professionals',
  tone: 'Authentic, High-Value, Engaging',
  key_points: JSON.stringify(metaObj),
  language: 'English',
  generated_content: fullContent,
  hashtags: hashtags,
  call_to_action: cta,
  status: 'approved'
};

return [{
  json: {
    ...record,
    video_url: ctx.cleanUrl,
    image_url: ctx.finalImageUrl,
    scheduled_at: ctx.scheduledAt,
    recordToSave: record
  }
}];

const items = $input.all();
if (!items || items.length === 0 || !items[0].json || items[0].json.length === 0) {
  return [];
}

const post = Array.isArray(items[0].json) ? items[0].json[0] : items[0].json;
if (!post || !post.id) {
  return [];
}

// Check if scheduled_at has arrived
let meta = {};
try {
  if (post.key_points && post.key_points.startsWith('{')) {
    meta = JSON.parse(post.key_points);
  }
} catch (e) {}

const scheduledAtStr = meta.scheduled_at;
if (scheduledAtStr) {
  const schedTime = new Date(scheduledAtStr).getTime();
  const nowTime = Date.now();
  if (schedTime > nowTime) {
    // Not due yet!
    return [];
  }
}

const content = (post.generated_content || '').trim();
const hashtags = (post.hashtags || '').trim();
const cta = (post.call_to_action || '').trim();
const fullText = `${content}\n\n${cta}\n\n${hashtags}`.trim();

return [{
  json: {
    ...post,
    fullText: fullText,
    linkedinText: fullText.slice(0, 2900),
    facebookText: fullText.slice(0, 4800),
    instagramCaption: fullText.slice(0, 2100),
    thumbnailUrl: meta.image_url || 'https://images.unsplash.com/photo-1618005182384-a83a8bd57fbe?w=1080&q=80'
  }
}];

